from pathlib import Path
import json,shutil,hashlib
root=Path(__file__).resolve().parent
repo=root.parents[1]
manifest=root/'execution-manifest.json'
data=json.loads(manifest.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
for entry in data['cases'][1:]:
    case=entry['case_id'];slug=case.rsplit('__',1)[-1];sub=root/'cases'/slug
    for candidate in ['primary','fallback1','fallback2','fallback3']:
        is_primary=candidate=='primary'
        if slug=='reverse_close_traffic_steady':
            offline=repo/'.runtime-work'/('c136014-'+slug+'-'+('offline-002' if is_primary else f'{candidate}-offline-001'))
            compat=repo/'.runtime-work'/('c136014-'+slug+'-'+('compat-002' if is_primary else f'{candidate}-compat-001'))
        else:
            offline=repo/'.runtime-work'/('c136014-'+slug+'-'+('offline-002' if is_primary else f'{candidate}-offline-001'))
            compat=repo/'.runtime-work'/('c136014-'+slug+'-'+('primary-compat-002' if is_primary else f'{candidate}-compat-002'))
        target=entry if is_primary else next(x for x in entry['candidates'] if x['id']==candidate)
        prefix='primary' if is_primary else candidate
        receipt=sub/f'{prefix}-compatibility.json';shutil.copyfile(compat/'compatibility.json',receipt)
        clog=sub/f'{prefix}-compat.log';shutil.copyfile(compat/'compatibility-analysis.log',clog)
        nlog=sub/f'{prefix}-negative.log';shutil.copyfile(compat/'negative-analysis.log',nlog)
        olog=sub/f'{prefix}-offline.log';shutil.copyfile(offline/'offline.log',olog)
        saved=sub/(('primary-saved-proof.log' if slug=='reverse_clear_traffic_brakes' else f'{slug}-saved-proof.log') if is_primary else f'{candidate}-saved-proof.log')
        assert saved.is_file() and json.loads(saved.read_text())['negative_missing_source_rejected']
        cmd=f'.venv-cpu/bin/python runtime.py offline --manifest work/{root.name}/execution-manifest.json --case {case}'
        if not is_primary:cmd+=f' --candidate {candidate}'
        cmd+=f' --output {offline.relative_to(repo)} --python {repo}/.venv-cpu/bin/python'
        target['offline']={'command':cmd,'exit_code':0,'log':str(olog.relative_to(root)),'log_sha256':sha(olog),'construction_sha256':target['construction_sha256']}
        target['compatibility']={'receipt':str(receipt.relative_to(root)),'sha256':sha(receipt),'log':str(clog.relative_to(root)),'negative_log':str(nlog.relative_to(root))}
        if is_primary:
            target['post_capture']={'recorded_only':True,'command':f'.venv-cpu/bin/python runtime.py process-saved --manifest work/{root.name}/execution-manifest.json --case {case} --attempt $ATTEMPT --output $OUTPUT --library runtime/library --validator $VALIDATOR','feedback_command':'cat $OUTPUT/v0001/feedback.json','test_log':str(saved.relative_to(root)),'test_log_sha256':sha(saved),'test_exit_code':0}
        else:
            target['saved_processing_test']={'command':f'.venv-cpu/bin/python work/{root.name}/prove_saved.py --manifest work/{root.name}/execution-manifest.json --validator $VALIDATOR --case {case} --candidate {candidate}','exit_code':0,'log':str(saved.relative_to(root)),'log_sha256':sha(saved)}
manifest.write_text(json.dumps(data,indent=2)+'\n')
print('bound',sum(1+len(e['candidates']) for e in data['cases'][1:]),'candidate receipts')

"""Three same-case physical-risk alternatives for each expanded backing case."""
from pathlib import Path
import json,hashlib
ROOT=Path(__file__).resolve().parent
manifest_path=ROOT/'execution-manifest.json';manifest=json.loads(manifest_path.read_text())
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
for entry in manifest['cases'][1:]:
    base=json.loads((ROOT/entry['construction']).read_text());slug=entry['case_id'].split('__')[-1]
    root=ROOT/'cases'/slug
    offset=10 if slug=='reverse_close_traffic_steady' else 18
    for i in (1,2,3):
        candidate=json.loads(json.dumps(base))
        def change(path,old,new):
            f=next(f for f in candidate['files'] if f['path']==path)
            if old not in f['content']:raise ValueError('Expected phrase changed: '+old)
            f['content']=f['content'].replace(old,new);f.pop('source',None)
        if i==1:
            change('runner.py',f'waypoint.previous({offset}.0)',f'waypoint.previous({offset-2}.0)')
            change('tests/test_runner.py',f"self.assertEqual(scene['other'].transform.location.x,-{offset})",
                   f"self.assertEqual(scene['other'].transform.location.x,-{offset-2})")
        elif i==2:change('runner.py','throttle=.22,reverse=True','throttle=.14,reverse=True')
        else:change('backing_camera_capture.py','"approach": ((1.2, 0.0, 2.0)',
                    '"approach": ((1.8, 0.0, 2.4)')
        p=root/(f'fallback{i}-construction.json');p.write_text(json.dumps(candidate,indent=2)+'\n')
        if i==1:
            trigger={'source':'Native waypoint selection diagnostic','metric':'connected rear spawn candidates',
                     'failure_condition':f'Primary {offset} m rear continuation absent; use {offset-2} m verified continuation'}
            knobs=[f'rear actor spawn offset {offset} m to {offset-2} m']
        elif i==2:
            trigger={'source':'original backing_history.jsonl actor positions','metric':'closing rate and minimum center distance',
                     'failure_condition':'Primary reverse control enters 2 m engineering collision-risk band before planned stop'}
            knobs=['ego reverse throttle 0.22 to 0.14']
        else:
            trigger={'source':'full decoded original approach RGB source','metric':'per-frame complete body visibility',
                     'failure_condition':'Subject or other vehicle body omitted from any original approach frame'}
            knobs=['approach camera mount x 1.2 to 1.8 m, z 2.0 to 2.4 m']
        entry['candidates'].append({'id':f'fallback{i}','construction':str(p.relative_to(ROOT)),
            'construction_sha256':sha(p),'trigger':trigger,'changed_knobs':knobs})
    entry['candidate_risk']={'status':'physical','reason':'Native map route, reverse control and original-camera coverage may independently fail'}
manifest_path.write_text(json.dumps(manifest,indent=2)+'\n')

"""Freeze two three-point engineering grids; no legal thresholds or labels."""
import json,hashlib,sys
from pathlib import Path
r=Path(__file__).resolve().parent;p=r/'proposals';repo=r.parents[1]
sys.path.insert(0,str(repo/'runtime/scenario_pipeline'))
from batch_pipeline.sweeps import expand_sweeps

def read(name):return json.loads((p/(name+'.json')).read_text())
def write(name,value):(p/(name+'.json')).write_text(json.dumps(value,indent=2)+'\n')
lid='NRS-484B-113-1'
template=read('template');bindings=read('bindings');cases=read('cases');observed=read('judgment_interference')
new={'name':'other_traffic_brake_start_frame','kind':'world_setup','range_or_domain':'brake onset frame in a fixed 160-frame capture','used_by_laws':[lid]}
if new['name'] not in [x['name'] for x in template['parameter_refs']]:template['parameter_refs'].append({k:v for k,v in new.items() if k!='used_by_laws'})
if new['name'] not in [x['name'] for x in bindings['variable_parameters']]:bindings['variable_parameters'].append(new)
req=observed['observable_requirements'];req['sweep_dimensions']=[{'name':'other_traffic_brake_start_frame','unit':'frame','description':'Authored onset of other-traffic braking within one frozen capture.'}]
for case in cases['cases']:
 if new['name'] not in case['variable_assignments']:case['variable_assignments'][new['name']]={'kind':'world_setup','value':80}
# The parent of each grid is an engineering controller or world setup, not a law cutoff.
base=cases['cases'][1]['recording_description'];brakes=cases['cases'][3]['recording_description']
axes=[
 (r.name+'__backing_safety_spacing_grid',[{'phrase':'reasonable safety','note':'No statutory numeric safety cutoff.'}], 'other_traffic_spacing','m',8,16,4,'minimum original actor-center distance over the backing interval','The 8–16 m commanded spawn range spans visible close and clear encounter geometry; 4 m spacing resolves an interior physical setting.',base),
 (r.name+'__backing_interference_onset_grid',[{'phrase':'without interfering with other traffic','note':'Traffic interference requires independent original-source observations.'}], 'other_traffic_brake_start_frame','frame',40,120,40,'other vehicle original speed change over the backing interval','Frames 40–120 bracket early and late braking within 160 captured frames; 40-frame spacing gives an interior onset.',brakes)]
specs=[]
for sid,refs,var,unit,low,high,step,method,rationale,description in axes:
 specs.append({'sweep_id':sid,'target_law_id':lid,'judgment_refs':refs,'status':'complete','mode':'one_dimensional','axes':[{'variable':var,'observable':var,'unit':unit,'min':low,'max':high,'spacing':step,'measurement':{'method':method,'time_window':'all original backing frames','statistic':'min' if unit=='m' else 'first'},'range_rationale':rationale,'spacing_rationale':'Three fixed physical settings including both endpoints and one interior point; no legal cutoff.','feasibility_evidence':'Native waypoint selection and timed control are encoded in the exact runner; actual realization requires retained original source review.'}], 'landmarks':[],'rationale':'Fixed three-point physical coverage; legal judgment remains unresolved.','variable_assignments':{'reverse_motion':{'kind':'subject_behavior','value':None},'other_traffic_spacing':{'kind':'world_setup','value':12.0},'other_traffic_speed_policy':{'kind':'world_setup','value':'braking' if unit=='frame' else 'steady'},'other_traffic_brake_start_frame':{'kind':'world_setup','value':80}},'recording_description':description})
cases['cases']=cases['cases'][:4];cases['sweep_specs']=specs;cases.pop('sweeps_expanded',None)
expand_sweeps(cases,[template],bindings)
write('template',template);write('bindings',bindings);write('judgment_interference',observed);write('cases',cases)
index=read('semantic-index')
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
for stage,reference in index['stages'].items():
 for ref in reference if isinstance(reference,list) else [reference]:ref['sha256']=sha(r/ref['path'])
write('semantic-index',index)
print('expanded',len(cases['cases']),'canonical cases including baseline;',sum(len(s['selection_order']) for s in specs),'fixed-grid points')

